('gate-puzzler','intermediate','What is the consensus theorem?',ARRAY['AB + A''C + BC = AB + A''C','AB + AC = AB','A+B = A','AB = A'],0,'Consensus: AB + A''C + BC = AB + A''C.',15),
('gate-puzzler','intermediate','Simplify: AB + AB''',ARRAY['A','B','A+B','0'],0,'AB + AB'' = A(B+B'') = A.',15),
